package reascer.wom.skill.weaponinnate;

import net.minecraft.network.FriendlyByteBuf;
import reascer.wom.gameasset.animations.weapons.AnimsOrbit;
import yesman.epicfight.skill.SkillBuilder;
import yesman.epicfight.skill.SkillContainer;
import yesman.epicfight.skill.weaponinnate.WeaponInnateSkill;

public class OrbitalBeamSkill
extends WeaponInnateSkill {
    public OrbitalBeamSkill(SkillBuilder<? extends WeaponInnateSkill> builder) {
        super(builder);
    }

    public void executeOnServer(SkillContainer container, FriendlyByteBuf args) {
        container.getExecutor().playAnimationSynchronized(AnimsOrbit.ORBIT_LIGHT_BEAM, 0.3f);
        super.executeOnServer(container, args);
    }

    public boolean canExecute(SkillContainer container) {
        if (container.getExecutor().getTarget() == null) {
            return false;
        }
        return super.canExecute(container);
    }
}

